<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'

type Candle = { date: string; close: number; open: number; high: number; low: number; volume: number }
type Holding = { symbol: string; shares: number; entryPrice: number; stop?: number; target?: number; openedDate?: string }
type Plan = { symbol: string; action: string; reasons: string[]; entry: number | null; stop: number | null; target: number | null; lots: number; estimatedCost: number; plannedRisk: number; asOf: string; expiry: string; strategyVersion: string }
type Dashboard = { histories: Record<string, Candle[]>; index: Candle[]; source: { asOf: string; fetchedAt: string; status: string; message: string }; holdings: Holding[]; settings: Record<string, number>; plans: Plan[]; backtest: any }
const page = ref('overview')
const busy = ref('loading')
const error = ref('')
const notice = ref('')
const data = ref<Dashboard | null>(null)
const holdings = ref<Holding[]>([])
const settings = reactive<Record<string, number>>({ cash: 10000000, equity: 10000000, riskPct: .5, maxPositionPct: 25, maxTotalRiskPct: 2, buyFeePct: .15, sellFeePct: .25, slippagePct: .1, minDailyValue: 1000000000, maxPositions: 4 })
const newHolding = reactive({ symbol: '', shares: 100, entryPrice: 0, stop: 0, target: 0, openedDate: '' })
const showAdvanced = ref(false)
const nav = [{ id: 'overview', icon: '◫', label: 'Ringkasan' }, { id: 'plans', icon: '↗', label: 'Trade planner' }, { id: 'holdings', icon: '▤', label: 'Portofolio' }, { id: 'backtest', icon: '⌁', label: 'Backtest' }]
const idr = (n: any) => Number.isFinite(Number(n)) && n !== null ? new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(n)) : '—'
const num = (n: any) => Number.isFinite(Number(n)) && n !== null ? new Intl.NumberFormat('id-ID', { maximumFractionDigits: 2 }).format(Number(n)) : '—'
const date = (s?: string) => s ? new Date(s.length === 10 ? s + 'T12:00:00+07:00' : s).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Asia/Jakarta' }) : 'Belum tersedia'
const indexRows = computed(() => [...(data.value?.index || [])].sort((a, b) => a.date.localeCompare(b.date)))
const latestIndex = computed(() => indexRows.value.at(-1))
const indexChange = computed(() => { const rows = indexRows.value; return rows.length > 1 ? (rows.at(-1)!.close / rows.at(-2)!.close - 1) * 100 : null })
const plans = computed(() => data.value?.plans || [])
const buyCount = computed(() => plans.value.filter(p => p.action === 'BUY').length)
const reserved = computed(() => plans.value.filter(p => p.action === 'BUY').reduce((sum, p) => sum + (p.estimatedCost || 0), 0))
const plannedRisk = computed(() => plans.value.filter(p => p.action === 'BUY').reduce((sum, p) => sum + (p.plannedRisk || 0), 0))
const activeTitle = computed(() => nav.find(n => n.id === page.value)?.label)
const report = computed(() => data.value?.backtest)
const testPeriod = ref('holdout')
const testResult = computed(() => report.value?.[testPeriod.value])
const performancePaths = computed(() => { const curve = testResult.value?.equityCurve || []; if (curve.length < 2) return { strategy: '', benchmark: '' }; const values = curve.flatMap((p: any) => [p.equity, p.benchmarkEquity]).filter(Number.isFinite); const min = Math.min(...values), max = Math.max(...values); const path = (key: string) => curve.map((p: any, i: number) => `${i ? 'L' : 'M'}${i / (curve.length - 1) * 760},${168 - (p[key] - min) / (max - min || 1) * 156}`).join(' '); return { strategy: path('equity'), benchmark: path('benchmarkEquity') } })
function chartPath(values: number[], w = 760, h = 180) { if (values.length < 2) return ''; const min = Math.min(...values), max = Math.max(...values); return values.map((v, i) => `${i ? 'L' : 'M'}${i / (values.length - 1) * w},${h - 12 - (v - min) / (max - min || 1) * (h - 24)}`).join(' ') }
const indexPath = computed(() => chartPath(indexRows.value.slice(-65).map(r => r.close)))
async function request(url: string, body?: unknown) { const r = await fetch(url, body ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : undefined); const payload = await r.json(); if (!r.ok) throw new Error(payload.statusMessage || payload.message || 'Permintaan gagal. Coba lagi.'); return payload }
function applyDashboard(payload: Dashboard) { data.value = payload; Object.assign(settings, payload.settings); holdings.value = payload.holdings || [] }
async function load() { busy.value = 'loading'; error.value = ''; try { applyDashboard(await request('/api/dashboard')) } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
async function refresh() { busy.value = 'refresh'; error.value = ''; notice.value = ''; try { data.value = await request('/api/refresh', {}); const planned = await request('/api/plan', { settings: { ...settings }, holdings: holdings.value }); if (data.value) data.value.plans = planned.plans; notice.value = 'Data diperbarui. Pengaturan Anda tetap dipertahankan. Periksa tanggal observasi.' } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
async function calculate(save = false) { busy.value = save ? 'save' : 'plan'; error.value = ''; notice.value = ''; try { const payload = await request(save ? '/api/portfolio' : '/api/plan', { settings: { ...settings }, holdings: holdings.value }); if (payload.plans && data.value) data.value.plans = payload.plans; if (payload.settings) Object.assign(settings, payload.settings); if (payload.holdings) holdings.value = payload.holdings; notice.value = save ? 'Pengaturan dan portofolio tersimpan.' : 'Rencana dihitung ulang dengan batas risiko Anda.' } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
function addHolding() { error.value = ''; const symbol = newHolding.symbol.trim().toUpperCase(); if (!/^[A-Z]{4}$/.test(symbol) || newHolding.shares <= 0 || !Number.isInteger(newHolding.shares) || newHolding.entryPrice <= 0 || newHolding.stop < 0 || newHolding.target < 0) { error.value = 'Isi kode saham 4 huruf, lembar positif, harga beli positif, dan stop yang valid.'; return } if (holdings.value.some(h => h.symbol === symbol)) { error.value = 'Saham sudah ada. Hapus posisi lama sebelum menggantinya.'; return } holdings.value.push({ symbol, shares: newHolding.shares, entryPrice: newHolding.entryPrice, ...(newHolding.stop > 0 ? { stop: newHolding.stop } : {}), ...(newHolding.target > 0 ? { target: newHolding.target } : {}), ...(newHolding.openedDate ? { openedDate: newHolding.openedDate } : {}) }); Object.assign(newHolding, { symbol: '', shares: 100, entryPrice: 0, stop: 0, target: 0, openedDate: '' }); notice.value = 'Posisi ditambahkan. Simpan untuk memperbarui rencana.' }
onMounted(load)
</script>

<template>
  <div class="workspace">
    <aside class="sidebar">
      <a class="brand" href="#" @click.prevent="page = 'overview'"><span class="brand-mark">s<span>↗</span></span><span>Swing<span class="brand-light">Lab</span><small>INDONESIA EQUITIES</small></span></a>
      <div class="workspace-label">PERSONAL WORKSPACE <span>01</span></div>
      <nav aria-label="Navigasi utama"><button v-for="item in nav" :key="item.id" :class="{ active: page === item.id }" @click="page = item.id"><span class="nav-icon">{{ item.icon }}</span>{{ item.label }}<span v-if="page === item.id" class="nav-dot"></span></button></nav>
      <div class="sidebar-note"><span class="tiny-label">METODE</span><h3>Rencana, bukan tebakan.</h3><p>Data harian. Aturan transparan. Risiko terukur.</p><span class="horizon-pill">3–15 sesi bursa</span></div>
      <div class="sidebar-footer"><span class="status-dot"></span> Mode edukasi & paper trading<small>Tidak terhubung ke broker</small></div>
    </aside>
    <main>
      <header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>{{ activeTitle }}</strong></div><div class="topbar-right"><span class="market-badge">IDX <i></i> END OF DAY</span><span class="avatar">P</span></div></header>
      <div class="content">
        <div class="page-heading"><div><div class="eyebrow">YOUR NEXT MOVE, WITH CONTEXT</div><h1>{{ page === 'overview' ? 'Pasar dalam perspektif.' : page === 'plans' ? 'Rencanakan risikonya.' : page === 'holdings' ? 'Kenali posisi Anda.' : 'Uji sebelum percaya.' }}</h1><p>{{ page === 'backtest' ? 'Simulasi historis dengan biaya, slippage, dan aturan eksekusi yang eksplisit.' : 'Ruang kerja pribadi untuk keputusan swing trading yang lebih terstruktur.' }}</p></div><button class="button secondary refresh-button" :disabled="!!busy" @click="refresh"><span :class="{ spinning: busy === 'refresh' }">↻</span> {{ busy === 'refresh' ? 'Memperbarui…' : 'Perbarui data' }}</button></div>
        <div v-if="error" class="message error" role="alert">{{ error }} <button v-if="!data" @click="load">Coba lagi</button></div>
        <div v-if="notice" class="message success" role="status">{{ notice }}</div>
        <div v-if="busy === 'loading'" class="loading-panel"><span class="loading-orbit"></span><h2>Menyiapkan ruang kerja</h2><p>Membaca data dan menghitung rencana…</p></div>
        <template v-else-if="data">
          <div class="source-line"><span class="source-tag"><span class="status-dot" :class="{ amber: data.source.status !== 'live' }"></span>{{ data.source.status === 'stale' ? 'Data belum terkini' : 'Snapshot tersimpan' }}</span><span>Observasi {{ date(data.source.asOf) }}</span><span class="source-description">{{ data.source.message }}</span></div>
          <template v-if="page === 'overview' || page === 'plans'">
            <section class="stat-grid" aria-label="Ringkasan angka"><article class="stat-card"><span class="stat-label">IHSG <span>↗</span></span><strong>{{ num(latestIndex?.close) }}</strong><small :class="indexChange !== null && indexChange < 0 ? 'negative' : 'positive'">{{ indexChange !== null ? `${indexChange >= 0 ? '+' : ''}${num(indexChange)}%` : '—' }} <span>vs sesi sebelumnya</span></small></article><article class="stat-card"><span class="stat-label">Modal tersedia <span>Rp</span></span><strong>{{ idr(settings.cash) }}</strong><small>Dana tunai untuk rencana baru</small></article><article class="stat-card"><span class="stat-label">Kandidat BUY <span>◎</span></span><strong>{{ buyCount }} <em>/ {{ plans.length }}</em></strong><small>Hanya saat seluruh filter lolos</small></article><article class="stat-card"><span class="stat-label">Risiko rencana baru <span>◇</span></span><strong>{{ idr(plannedRisk) }}</strong><small>Stop bukan jaminan batas rugi</small></article></section>
            <div class="main-grid">
              <div class="main-column">
                <section v-if="page === 'overview'" class="panel chart-panel"><div class="panel-heading"><div><span class="tiny-label">MARKET PULSE</span><h2>Indeks Harga Saham Gabungan</h2></div><span class="subtle-pill">65 sesi terakhir</span></div><div v-if="indexPath" class="index-chart"><div class="chart-gridlines"><span></span><span></span><span></span></div><svg viewBox="0 0 760 180" role="img" aria-label="Grafik penutupan IHSG 65 sesi terakhir" preserveAspectRatio="none"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--accent)" stop-opacity=".17"/><stop offset="100%" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs><path :d="`${indexPath} L760,180 L0,180 Z`" fill="url(#chart-fill)"/><path :d="indexPath" fill="none" stroke="var(--accent)" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div v-else class="empty-inline">Data indeks belum tersedia.</div><div class="chart-footer"><span>{{ date(indexRows.slice(-65)[0]?.date) }}</span><span>Penutupan harian · Arjum</span><span>{{ date(latestIndex?.date) }}</span></div></section>
                <section class="panel plans-panel"><div class="panel-heading"><div><span class="tiny-label">TRADE PLAN TEKNIKAL</span><h2>{{ page === 'overview' ? 'Watchlist & rencana' : 'Rencana berdasarkan modal' }}</h2></div><span class="subtle-pill">{{ plans.length }} saham</span></div><p class="panel-description">BUY adalah pemicu simulasi. Hitung ulang ukuran pada harga eksekusi; lewati gap di atas 3%. WAIT adalah hasil yang valid.</p><div class="table-scroll"><table class="plans-table"><thead><tr><th>Saham / status</th><th>Entry / stop</th><th>Target</th><th>Ukuran</th><th>Risiko</th></tr></thead><tbody><template v-for="plan in plans" :key="plan.symbol"><tr><td><strong class="symbol">{{ plan.symbol }}</strong><span :class="['action-pill', plan.action.toLowerCase()]">{{ plan.action }}</span></td><td>{{ idr(plan.entry) }}<small class="cell-secondary">Stop {{ idr(plan.stop) }}</small></td><td>{{ idr(plan.target) }}</td><td>{{ num(plan.lots) }} lot<small class="cell-secondary">{{ idr(plan.estimatedCost) }}</small></td><td>{{ idr(plan.plannedRisk) }}</td></tr><tr class="reason-row"><td colspan="5"><span class="reason-marker">↳</span>{{ plan.reasons.join(' · ') }}<span v-if="plan.expiry" class="expiry">Berlaku: {{ plan.expiry === 'NEXT_TRADING_SESSION_ONLY' ? 'sesi bursa berikutnya saja' : plan.expiry }}</span></td></tr></template></tbody></table></div><div v-if="!plans.length" class="empty-inline">Belum ada rencana. Periksa data lalu hitung ulang.</div><div class="panel-bottom"><span>Alokasi rencana BUY</span><strong>{{ idr(reserved) }}</strong></div></section>
              </div>
              <aside class="right-column"><section class="panel capital-panel"><div class="panel-heading"><div><span class="tiny-label">YOUR PARAMETERS</span><h2>Modal & risiko</h2></div><span class="settings-icon">⚙</span></div><form @submit.prevent="calculate()"><label class="field-label" for="cash">Dana tersedia <span>IDR</span></label><input id="cash" v-model.number="settings.cash" type="number" min="0" step="1" required class="capital-input"/><label class="field-label" for="equity">Total ekuitas portofolio <span>IDR</span></label><input id="equity" v-model.number="settings.equity" type="number" min="0" step="1" required/><p class="field-help">Total ekuitas sudah termasuk Dana tersedia + nilai pasar saham. Belum punya saham? Isi keduanya sama. Keduanya boleh 0.</p><button v-if="!holdings.length" type="button" class="text-button advanced-toggle" @click="settings.equity = settings.cash ?? 0">Samakan ekuitas dengan dana tersedia</button><div class="field-pair"><div><label class="field-label" for="risk">Risiko / trade (%)</label><input id="risk" v-model.number="settings.riskPct" type="number" min="0" max="5" step="0.01" required/></div><div><label class="field-label" for="cap">Batas posisi (%)</label><input id="cap" v-model.number="settings.maxPositionPct" type="number" min="1" max="100" step="1" required/></div></div><button type="button" class="text-button advanced-toggle" @click="showAdvanced = !showAdvanced">{{ showAdvanced ? '−' : '+' }} Pengaturan lanjutan</button><div v-if="showAdvanced" class="advanced-fields"><label v-for="field in [{key:'maxTotalRiskPct',label:'Total risiko terbuka (%)',step:.1},{key:'buyFeePct',label:'Biaya beli (%)',step:.01},{key:'sellFeePct',label:'Biaya jual (%)',step:.01},{key:'slippagePct',label:'Slippage (%)',step:.01},{key:'maxPositions',label:'Maksimal posisi',step:1},{key:'minDailyValue',label:'Minimal nilai harian (Rp)',step:100000000}]" :key="field.key" class="field-label">{{ field.label }}<input v-model.number="settings[field.key]" type="number" min="0" :step="field.step" required/></label></div><button class="button primary full" :disabled="!!busy" type="submit">{{ busy === 'plan' ? 'Menghitung…' : 'Hitung rencana' }} <span>↗</span></button><button class="button quiet full" :disabled="!!busy" type="button" @click="calculate(true)">{{ busy === 'save' ? 'Menyimpan…' : 'Simpan pengaturan' }}</button></form></section><section class="insight-card"><span class="insight-icon">◇</span><span class="tiny-label">DISIPLIN LEBIH DULU</span><h3>Tidak selalu harus masuk pasar.</h3><p>Ukuran posisi dibatasi modal, risiko, likuiditas, dan total eksposur. Dana boleh tetap tunai.</p></section></aside>
            </div>
          </template>
          <template v-else-if="page === 'holdings'"><section class="panel"><div class="panel-heading"><div><span class="tiny-label">MANUAL PORTFOLIO</span><h2>Posisi yang Anda miliki</h2></div><button class="button primary" :disabled="!!busy" @click="calculate(true)">Simpan portofolio</button></div><p class="panel-description">SELL hanya berlaku untuk posisi tercatat. Universe awal: BBCA, BBRI, TLKM, ANTM. Masukkan jumlah lembar, bukan jumlah lot.</p><form class="holding-form" @submit.prevent="addHolding"><label>Kode saham<select v-model="newHolding.symbol" required><option disabled value="">Pilih saham</option><option v-for="symbol in ['BBCA', 'BBRI', 'TLKM', 'ANTM']" :key="symbol">{{ symbol }}</option></select></label><label>Jumlah lembar<input v-model.number="newHolding.shares" type="number" min="1" step="1" required/></label><label>Harga beli / lembar<input v-model.number="newHolding.entryPrice" type="number" min="1" required/></label><label>Stop / lembar (opsional)<input v-model.number="newHolding.stop" type="number" min="0"/></label><label>Target / lembar (opsional)<input v-model.number="newHolding.target" type="number" min="0"/></label><label>Tanggal beli (opsional)<input v-model="newHolding.openedDate" type="date"/></label><button class="button secondary" type="submit">+ Tambah</button></form><div class="table-scroll"><table><thead><tr><th>Saham</th><th>Lembar</th><th>Harga beli</th><th>Stop</th><th>Target</th><th></th></tr></thead><tbody><tr v-for="(h, i) in holdings" :key="h.symbol"><td class="symbol">{{ h.symbol }}</td><td>{{ num(h.shares) }}</td><td>{{ idr(h.entryPrice) }}</td><td>{{ h.stop ? idr(h.stop) : 'Belum diisi' }}</td><td>{{ h.target ? idr(h.target) : 'Belum diisi' }}</td><td><button class="text-button negative" @click="holdings.splice(i, 1)">Hapus</button></td></tr></tbody></table></div><div v-if="!holdings.length" class="empty-state"><span>▤</span><h3>Mulai dengan posisi pertama</h3><p>Portofolio kosong. Anda tetap dapat menghitung rencana pembelian.</p></div></section></template>
          <template v-else-if="page === 'backtest'"><section class="panel"><div class="panel-heading"><div><span class="tiny-label">RESEARCH, NOT A PROMISE</span><h2>Hasil pengujian historis</h2></div><span class="subtle-pill">Eksploratif</span></div><div class="research-warning"><strong>Belum merupakan bukti strategi yang tervalidasi.</strong><p>Penyesuaian aksi korporasi belum sepenuhnya terverifikasi. Universe saham saat ini dapat menimbulkan survivorship bias.</p></div><template v-if="report"><p class="panel-description">Universe: {{ report.universe?.join(', ') }} · Laporan {{ date(report.generatedAt) }} · {{ report.strategyVersion }}</p><div class="period-tabs"><button :class="{ selected: testPeriod === 'holdout' }" @click="testPeriod = 'holdout'">Evaluasi holdout</button><button :class="{ selected: testPeriod === 'development' }" @click="testPeriod = 'development'">Periode pengembangan</button></div><template v-if="testResult"><div class="backtest-date">{{ date(testResult.startDate) }} — {{ date(testResult.endDate) }}</div><div class="backtest-stats"><article><span>Return bersih</span><strong :class="testResult.totalReturnPct < 0 ? 'negative' : 'positive'">{{ num(testResult.totalReturnPct) }}%</strong><small>Setelah biaya & slippage</small></article><article><span>Drawdown maksimum</span><strong>{{ num(testResult.maxDrawdownPct) }}%</strong><small>Penurunan dari puncak ekuitas</small></article><article><span>Transaksi selesai</span><strong>{{ num(testResult.tradeCount) }}</strong><small>Win rate {{ num(testResult.winRatePct) }}%</small></article><article><span>Benchmark</span><strong>{{ num(testResult.benchmarkReturnPct) }}%</strong><small>Modal awal yang sebanding</small></article></div><div class="backtest-chart-heading"><h3>Pertumbuhan ekuitas</h3><span><i class="strategy-legend"></i> Strategi <i class="benchmark-legend"></i> Benchmark</span></div><div v-if="performancePaths.strategy" class="index-chart backtest-chart"><div class="chart-gridlines"><span></span><span></span><span></span></div><svg viewBox="0 0 760 180" role="img" aria-label="Perbandingan kurva ekuitas strategi dan benchmark" preserveAspectRatio="none"><path :d="performancePaths.benchmark" fill="none" stroke="var(--muted)" stroke-width="1.5" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/><path :d="performancePaths.strategy" fill="none" stroke="var(--accent)" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div class="backtest-details"><span>Ekuitas akhir <strong>{{ idr(testResult.finalEquity) }}</strong></span><span>Ekspektansi / trade <strong>{{ idr(testResult.expectancy) }}</strong></span><span>Entri dilewati <strong>{{ num(testResult.skippedEntries) }}</strong></span></div><div class="table-scroll"><table><thead><tr><th>Saham</th><th>Masuk → keluar</th><th>Lembar</th><th>P/L bersih</th><th>Alasan keluar</th></tr></thead><tbody><tr v-for="(trade, i) in [...(testResult.trades || [])].reverse().slice(0, 30)" :key="i"><td class="symbol">{{ trade.symbol }}</td><td>{{ date(trade.entryDate) }}<small class="cell-secondary">{{ date(trade.exitDate) }}</small></td><td>{{ num(trade.shares) }}</td><td :class="trade.netPnl < 0 ? 'negative' : 'positive'">{{ idr(trade.netPnl) }}</td><td>{{ trade.reason }}</td></tr></tbody></table></div><div v-if="!testResult.trades?.length" class="empty-inline">Tidak ada transaksi pada periode ini. Hasil nol transaksi tidak membuktikan kualitas strategi.</div><div v-if="testResult.openPositions?.length" class="open-positions-note">{{ testResult.openPositions.length }} posisi masih terbuka pada akhir periode. Ekuitas akhir memasukkan nilai pasar posisi ini; statistik transaksi selesai tidak memasukkannya.</div><p class="panel-description" style="margin-top: 16px">Menampilkan maksimal 30 transaksi terakhir. Seluruh transaksi tersedia dalam laporan lokal.</p></template><section v-if="report.sensitivity?.length" class="sensitivity-panel"><h3>Sensitivitas biaya · periode evaluasi</h3><p class="panel-description">Aturan tetap; bukan pencarian parameter terbaik. Modal simulasi Rp10.000.000, terpisah dari pengaturan planner.</p><div class="table-scroll"><table><thead><tr><th>Skenario</th><th>Return bersih</th><th>Drawdown</th><th>Transaksi</th></tr></thead><tbody><tr v-for="scenario in report.sensitivity" :key="scenario.name"><td>{{ scenario.name }}</td><td>{{ num(scenario.returnPct) }}%</td><td>{{ num(scenario.maxDrawdownPct) }}%</td><td>{{ scenario.trades }}</td></tr></tbody></table></div></section><details class="assumptions"><summary>Asumsi & keterbatasan pengujian</summary><ul><li v-for="(warning, i) in [...(report.warnings || []), ...(report.assumptions || [])]" :key="i">{{ warning }}</li></ul></details></template><div v-else class="empty-state"><span>⌁</span><h3>Belum ada laporan backtest</h3><p>Jalankan pengujian lokal terlebih dahulu. Hasil akan tampil di sini setelah tersedia.</p></div></section></template>
          <footer class="content-footer"><span>SwingLab <span class="footer-divider">/</span> Personal research workspace</span><span>Data: Arjum · Bukan instruksi transaksi otomatis</span></footer>
        </template>
      </div>
    </main>
  </div>
</template>





